{
  "name": "idle-micro-compact",
  "version": "0.4.1",
  "description": "Compacts an idle session before its prompt cache expires: first by masking old tool results and dropping thinking with no model call, falling back to a summary when that would not shrink it enough.",
  "author": {
    "name": "Kyle Schwartz"
  },
  "license": "MIT",
  "keywords": [
    "compact",
    "prompt-cache",
    "idle",
    "micro-compaction",
    "mod"
  ],
  "types": "./types/index.d.ts",
  "userConfig": {
    "idleMinutes": {
      "type": "number",
      "title": "Idle minutes",
      "description": "Minutes idle before compacting. The default of 50 leaves 10 minutes before a 1-hour prompt cache expires.",
      "default": 50,
      "min": 0
    },
    "minTokens": {
      "type": "number",
      "title": "Minimum conversation tokens",
      "description": "Leave smaller conversations alone: re-reading them cold is cheap. The system prompt and tools don't count.",
      "default": 40000,
      "min": 0
    },
    "microTargetTokens": {
      "type": "number",
      "title": "Micro-compaction target",
      "description": "Mask old tool results and drop thinking, with no model call, when that is estimated to leave the conversation at or under this many tokens. Above it, write a summary instead.",
      "default": 150000,
      "min": 0
    },
    "minSavedShare": {
      "type": "number",
      "title": "Minimum trim saving",
      "description": "Leave the conversation alone when a trim is estimated to save less than this share of it, from 0 to 1: 0.1 is 10%. A trim rewrites the transcript, so the next request writes all of it to the cache again.",
      "default": 0.1,
      "min": 0,
      "max": 1
    }
  }
}

